201	        '<label><input type="radio" name="' + f.key + '-op" value="keep" checked> 保持原值</label>' +
202	        '<label><input type="radio" name="' + f.key + '-op" value="set"> 设为填写的值</label>' +
203	        '<label><input type="radio" name="' + f.key + '-op" value="clear"> 清空</label>' +
