211	      "</p></div>").join("");
212	  wrap.querySelectorAll(".bf").forEach(card => {
213	    const input = card.querySelector(".bf-value");
214	    card.querySelectorAll('input[type=radio]').forEach(radio => radio.addEventListener("change", () => {
215	      const op = card.querySelector('input[type=radio]:checked').value;
