227	    if (op === "keep") {
228	      updates[key] = {op: "keep"};
229	    } else if (op === "clear") {
230	      updates[key] = {op: "clear"};
231	    } else {
232	      updates[key] = {op: "set", value: card.querySelector(".bf-value").value};
233	    }
234	  }
235	  return {ids: [...selected].sort((a, b) => a - b), updates};
