274	document.getElementById("batch-form").addEventListener("submit", async e => {
275	  e.preventDefault();
276	  // 等待结果期间再次提交（重复点击、回车等）一律忽略：不增加请求、不提前显示成功、
277	  // 不清除已填内容；等待期间的勾选变化也不会在结果返回后自动补交。
278	  if (batchSaving) return;
279	  if (!selected.size) {
280	    showBatchReport('<div class="banner bad">请先勾选至少一名客户。</div>');
281	    syncSubmitState();
282	    return;
283	  }
284	  // 以本次点击时的勾选与填写为准，固化请求内容；等待期间勾选变化不影响本次请求。
285	  const payload = collectBatchPayload();
286	  batchSaving = true;
287	  syncSubmitState();
288	  showBatchReport('<div class="banner busy">正在保存本次批量修改，请勿重复提交…</div>');
289	  try {
290	    const res = await fetch("/api/clients/batch-update", {
291	      method: "POST",
292	      headers: {"Content-Type": "application/json"},
293	      body: JSON.stringify(payload),
294	    });
295	    const data = await res.json();
296	    if (!res.ok) {
297	      // 服务明确拒绝：显示具体原因，保留当时页面上的勾选、字段操作及填写内容，
298	      // 由用户修正后主动再次保存。
299	      showBatchReport('<div class="banner bad">本次修改已全部拒绝，客户资料保持原样。<br>原因：' +
300	        esc(data.error || "未知错误") + "</div>");
301	      return;
302	    }
303	    const count = data.updated_count;
304	    resetBatchForm();
305	    selected.clear();
306	    await loadClients();
307	    showBatchReport('<div class="banner ok">已成功处理 <b>' + esc(count) +
308	      "</b> 名客户，相关列已刷新，勾选已清除。</div>");
309	  } catch (err) {
310	    // 请求失败也要结束等待并显示失败，不能使页面一直无法继续使用。
311	    showBatchReport('<div class="banner bad">批量修改请求失败：' + esc(err.message) + "</div>");
312	  } finally {
313	    // 等待结束：是否能保存仍取决于有没有选中客户（成功后已清除勾选）。
314	    batchSaving = false;
315	    syncSubmitState();
316	  }
317	});
