379	
380	class FileError(Exception):
381	    """文件级错误：整份文件拒绝导入（HTTP 400）。"""
382	
383	
384	class BatchUpdateError(Exception):
385	    """批量修改请求级错误：整次修改拒绝（HTTP 400）。"""
386	
387	
388	FIELD_LABELS = {
389	    "source": "来源",
390	    "region": "地区",
391	    "industry": "行业",
392	    "important_date": "重要日期",
393	}
394	
395	
396	def _normalize_set_value(field_name, value):
397	    """校验 set 操作的值并返回最终入库值；非法时抛 BatchUpdateError。
398	
399	    去除前后空白；仅含空白按清空（None）处理；来源/地区/行业保留内部空白与换行；
400	    重要日期非空时须为 YYYY-MM-DD 真实日历日期。
401	    """
402	    if not isinstance(value, str):
403	        raise BatchUpdateError("%s的设置值不是文本" % FIELD_LABELS[field_name])
404	    text = value.strip()
405	    if not text:
406	        return None
407	    if field_name == "important_date":
408	        ok, reason = check_date(text)
409	        if not ok:
410	            raise BatchUpdateError(reason)
411	    return text
412	
413	
414	def batch_update_clients(database, payload):
415	    """执行批量修改，返回 {"updated_count": 去重后的客户数}；非法请求抛 BatchUpdateError。
416	
417	    任一问题都整次拒绝，不写入任何客户。
418	    """
419	    if not isinstance(payload, dict):
420	        raise BatchUpdateError("请求体必须是 JSON 对象")
421	
422	    raw_ids = payload.get("ids")
423	    if not isinstance(raw_ids, list):
424	        raise BatchUpdateError("ids 必须是客户编号数组")
425	    if not raw_ids:
426	        raise BatchUpdateError("未选择客户：请先勾选至少一名客户")
427	
428	    ids = []
429	    seen_ids = set()
430	    for raw_id in raw_ids:
431	        if isinstance(raw_id, bool) or not isinstance(raw_id, int) or raw_id <= 0:
432	            raise BatchUpdateError("客户编号必须是正整数：%r 不合法" % (raw_id,))
433	        if raw_id not in seen_ids:
434	            seen_ids.add(raw_id)
435	            ids.append(raw_id)
436	
437	    raw_updates = payload.get("updates", {})
438	    if not isinstance(raw_updates, dict):
439	        raise BatchUpdateError("updates 必须是字段修改说明对象")
440	    extra = [key for key in raw_updates if key not in OPTIONAL_FIELDS]
441	    if extra:
442	        raise BatchUpdateError("包含不能修改或不存在的字段：%s" % "、".join(extra))
443	
444	    actions = {}
445	    for field_name in OPTIONAL_FIELDS:
446	        spec = raw_updates.get(field_name, {"op": "keep"})
447	        if not isinstance(spec, dict):
448	            raise BatchUpdateError("%s的修改说明必须是对象" % FIELD_LABELS[field_name])
449	        op = spec.get("op")
450	        if op not in ("keep", "set", "clear"):
451	            raise BatchUpdateError(
452	                "%s的操作必须是 keep、set 或 clear 之一" % FIELD_LABELS[field_name])
453	        if op == "keep":
454	            continue
455	        if op == "clear":
456	            actions[field_name] = None
457	        else:
458	            actions[field_name] = _normalize_set_value(field_name, spec.get("value"))
459	
460	    if not actions:
461	        raise BatchUpdateError("全部字段均保持原值：请至少选择一个字段进行设置或清空")
462	
463	    placeholders = ",".join("?" for _ in ids)
464	    existing = {
465	        row[0]
466	        for row in database.execute(
467	            "SELECT id FROM clients WHERE id IN (%s)" % placeholders, ids
468	        )
469	    }
470	    missing = [cid for cid in ids if cid not in existing]
471	    if missing:
472	        raise BatchUpdateError("找不到对应客户，编号：%s" % "、".join(str(c) for c in missing))
473	
474	    assignments = ", ".join("%s = ?" % field_name for field_name in actions)
475	    params = list(actions.values()) + ids
476	    try:
477	        database.execute(
478	            "UPDATE clients SET %s WHERE id IN (%s)" % (assignments, placeholders), params
479	        )
480	        database.commit()
481	    except sqlite3.DatabaseError:
482	        database.rollback()
483	        raise BatchUpdateError("保存失败：数据库错误，本次修改未生效")
484	
485	    return {"updated_count": len(ids)}
486	
487	
488	def parse_csv(text):
489	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
490	
491	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
492	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError：
493	    - 未加引号的字段中出现双引号（双引号只能在字段开头用于包住整个字段）；
494	    - 结束引号后出现逗号、换行或文件结束以外的字符（含空格）；
495	    - 文件结束时仍有字段处于引号内（引号未闭合）。
496	    错误信息区分上述三种情况，并指出发生在表头还是第 N 条数据记录
497	    （数据记录编号不包含表头，引号字段内的换行不增加编号）。
498	    """
499	    rows = []
500	    record = []
501	    field = []
502	    quoted = False        # 当前字段处于引号内
503	    started = False       # 当前字段已经开始（已有内容或已进入引号）
504	    closed = False       # 引号字段刚结束，等待逗号 / 换行 / 文件结束
505	    record_number = 0     # 0 = 表头，1 起为数据记录
506	    i = 0
507	    n = len(text)
508	
509	    def location():
510	        return "表头" if record_number == 0 else "第 %d 条数据记录" % record_number
511	
512	    def structure_error(kind):
513	        raise FileError("CSV 结构损坏（%s）：%s" % (location(), kind))
514	
515	    def finish_record():
516	        nonlocal record, field, started, closed
517	        record.append("".join(field))
518	        rows.append(record)
519	        record = []
520	        field = []
521	        started = False
522	        closed = False
523	
524	    while i < n:
525	        c = text[i]
526	        if quoted:
527	            if c == '"':
528	                if i + 1 < n and text[i + 1] == '"':
529	                    field.append('"')
530	                    i += 2
531	                    continue
532	                quoted = False
533	                closed = True
534	                i += 1
535	                continue
536	            if c == "\r":
537	                # 统一字段内换行符为 LF
538	                if i + 1 < n and text[i + 1] == "\n":
539	                    i += 1
540	                field.append("\n")
541	                i += 1
542	                continue
543	            field.append(c)
544	            i += 1
545	            continue
546	        if closed:
547	            # 引号已结束，只允许逗号、记录换行或文件结束
548	            if c == ",":
549	                record.append("".join(field))
550	                field = []
551	                started = False
552	                closed = False
553	            elif c in "\r\n":
554	                if c == "\r" and i + 1 < n and text[i + 1] == "\n":
555	                    i += 1
556	                finish_record()
557	                record_number += 1
558	            else:
559	                structure_error("结束引号后有多余字符，结束引号后只能紧接逗号、记录换行或文件结束")
560	            i += 1
561	            continue
562	        if c == '"' and not started:
563	            quoted = True
564	            started = True
565	        elif c == '"':
566	            structure_error("未加引号的字段中出现双引号，双引号只能在字段开头用于包住整个字段")
567	        elif c == ",":
568	            record.append("".join(field))
569	            field = []
570	            started = False
571	        elif c in "\r\n":
572	            if c == "\r" and i + 1 < n and text[i + 1] == "\n":
573	                i += 1
574	            if not started and not record and not field:
575	                # 空白行：不作为数据记录（显式的 "" 空字段 started=True，仍会保留）
576	                i += 1
577	                continue
578	            finish_record()
579	            record_number += 1
580	        else:
581	            field.append(c)
582	            started = True
583	        i += 1
584	    if quoted:
585	        structure_error("引号未闭合，文件结束时仍有字段处于引号内")
586	    if started or field or record or closed:
587	        record.append("".join(field))
588	        rows.append(record)
589	    if not rows:
590	        raise FileError("CSV 内容为空：缺少表头")
591	    return rows[0], rows[1:]
592	
593	
594	def check_date(value):
595	    """校验 YYYY-MM-DD 且为真实日历日期，返回 (是否合法, 错误原因)。"""
596	    match = DATE_RE.match(value)
597	    if not match:
598	        return False, "重要日期格式无效（%s）：须为 YYYY-MM-DD" % value
599	    try:
600	        datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
601	    except ValueError:
602	        return False, "重要日期无效（%s）：不是真实日历日期" % value
603	    return True, None
604	
605	
606	def import_clients(database, text):
607	    """执行导入，返回响应字典；文件级错误抛 FileError。"""
608	    header, data_rows = parse_csv(text)
609	    headers = [h.strip() for h in header]
610	
611	    seen = set()
612	    duplicates = []
613	    for h in headers:
614	        if h in seen and h not in duplicates:
615	            duplicates.append(h)
616	        seen.add(h)
617	    if duplicates:
618	        raise FileError("表头重复：%s" % "、".join(repr(h) for h in duplicates))
619	    unknown = [h for h in headers if h not in ALL_COLUMNS]
620	    if unknown:
621	        raise FileError("出现未知列：%s" % "、".join(repr(h) for h in unknown))
622	    if "name" not in headers:
623	        raise FileError("缺少名称列：表头必须包含 name 列")
624	
625	    index = {h: i for i, h in enumerate(headers)}
626	    name_index = index["name"]
627	    date_index = index.get("important_date")
628	
629	    existing = {}
630	    for cid, cname in database.execute("SELECT id, name FROM clients"):
631	        existing[(cname or "").strip().casefold()] = cid
632	
633	    imported = []
634	    failures = []
635	    seen_in_file = {}
636	
637	    for row_number, raw in enumerate(data_rows, start=1):
638	        if len(raw) != len(headers):
639	            failures.append({
640	                "row": row_number,
641	                "reason": "列数不符：表头有 %d 列，该记录有 %d 列" % (len(headers), len(raw)),
642	            })
643	            continue
644	
645	        name = raw[name_index].strip()
646	        problems = []
647	        if not name:
648	            problems.append("缺少名称：name 列为空")
649	        date_value = ""
650	        if date_index is not None:
651	            date_value = raw[date_index].strip()
652	            if date_value:
653	                ok, reason = check_date(date_value)
654	                if not ok:
655	                    problems.append(reason)
656	        if problems:
657	            failures.append({"row": row_number, "reason": "；".join(problems)})
658	            continue
659	
660	        key = name.casefold()
661	        if key in existing:
662	            failures.append({
663	                "row": row_number,
664	                "reason": "名称与已有客户重复（已有客户编号 %d），未更新" % existing[key],
665	            })
666	            continue
667	        if key in seen_in_file:
668	            failures.append({
669	                "row": row_number,
670	                "reason": "名称与文件内第 %d 条记录重复" % seen_in_file[key],
671	            })
672	            continue
673	
674	        seen_in_file[key] = row_number
675	        record = {"name": name}
676	        for field_name in OPTIONAL_FIELDS:
677	            idx = index.get(field_name)
678	            value = raw[idx].strip() if idx is not None else ""
679	            record[field_name] = value or None
680	        imported.append((row_number, record))
681	
682	    saved = []
683	    for row_number, record in imported:
684	        cursor = database.execute(
685	            "INSERT INTO clients (name, source, region, industry, important_date)"
686	            " VALUES (:name, :source, :region, :industry, :important_date)",
687	            record,
688	        )
689	        saved.append({"row": row_number, "id": cursor.lastrowid, "name": record["name"]})
690	    database.commit()
691	
692	    return {
693	        "imported_count": len(saved),
694	        "failed_count": len(failures),
695	        "imported": saved,
696	        "failures": failures,
697	    }
698	
699	
700	def main():
701	    parser = argparse.ArgumentParser(description="ClientBook - 客户联系人与商机记录")
702	    commands = parser.add_subparsers(dest="command", required=True)
703	    serve = commands.add_parser("serve", help="Start the HTTP service")
704	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
705	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
706	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
707	    args = parser.parse_args()
708	    if not 0 <= args.port <= 65535:
709	        parser.error("port must be between 0 and 65535")
710	    args.data_dir.mkdir(parents=True, exist_ok=True)
711	    database = sqlite3.connect(args.data_dir / "client-book.sqlite")
712	    database.execute("CREATE TABLE IF NOT EXISTS clients (id INTEGER PRIMARY KEY, name TEXT NOT NULL)")
713	    columns = {row[1] for row in database.execute("PRAGMA table_info(clients)")}
714	    for field_name in OPTIONAL_FIELDS:
715	        if field_name not in columns:
716	            database.execute("ALTER TABLE clients ADD COLUMN %s TEXT" % field_name)
717	    database.commit()
718	
719	    class Handler(BaseHTTPRequestHandler):
720	        def respond(self, status, value, *, html=False, allow=None):
721	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
722	            self.send_response(status)
723	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
724	            self.send_header("Content-Length", str(len(payload)))
725	            if status == 405:
726	                self.send_header("Allow", allow or "GET")
727	            self.end_headers()
728	            self.wfile.write(payload)
729	
730	        def handle_import(self):
731	            try:
732	                length = int(self.headers.get("Content-Length") or 0)
733	            except ValueError:
734	                length = 0
735	            if length > MAX_BODY:
736	                self.respond(400, {"error": "文件过大：超过 %d 字节上限" % MAX_BODY})
737	                return
738	            raw_body = self.rfile.read(length) if length > 0 else b""
739	            try:
740	                text = raw_body.decode("utf-8-sig")
741	            except UnicodeDecodeError:
742	                self.respond(400, {"error": "编码错误：文件不是有效的 UTF-8 文本"})
743	                return
744	            try:
745	                result = import_clients(database, text)
746	            except FileError as exc:
747	                database.rollback()
748	                self.respond(400, {"error": str(exc)})
749	                return
750	            self.respond(200, result)
751	
752	        def handle_batch_update(self):
753	            try:
754	                length = int(self.headers.get("Content-Length") or 0)
755	            except ValueError:
756	                length = 0
757	            if length > MAX_BODY:
758	                self.respond(400, {"error": "请求体过大：超过 %d 字节上限" % MAX_BODY})
759	                return
760	            raw_body = self.rfile.read(length) if length > 0 else b""
761	            try:
762	                payload = json.loads(raw_body.decode("utf-8"))
763	            except (UnicodeDecodeError, json.JSONDecodeError):
764	                self.respond(400, {"error": "请求体不是有效的 UTF-8 JSON 对象"})
765	                return
766	            try:
767	                result = batch_update_clients(database, payload)
768	            except BatchUpdateError as exc:
769	                database.rollback()
770	                self.respond(400, {"error": str(exc)})
771	                return
772	            self.respond(200, result)
773	
774	        def route(self):
775	            location = urlsplit(self.path).path
776	            if location not in (
777	                "/", "/health", "/api/clients",
778	                "/api/clients/import", "/api/clients/batch-update",
779	            ):
780	                self.respond(404, {"error": "not found"})
781	                return
782	            if location == "/api/clients/import":
783	                if self.command != "POST":
784	                    self.respond(405, {"error": "method not allowed"}, allow="POST")
785	                    return
786	                self.handle_import()
787	                return
788	            if location == "/api/clients/batch-update":
789	                if self.command != "POST":
790	                    self.respond(405, {"error": "method not allowed"}, allow="POST")
791	                    return
792	                self.handle_batch_update()
793	                return
794	            if self.command != "GET":
795	                self.respond(405, {"error": "method not allowed"}, allow="GET")
796	                return
797	            if location == "/":
798	                self.respond(200, PAGE, html=True)
799	            elif location == "/health":
800	                self.respond(200, {"status": "ok", "product": PRODUCT})
801	            else:
802	                records = [
803	                    {
804	                        "id": row[0],
805	                        "name": row[1],
806	                        "source": row[2],
807	                        "region": row[3],
808	                        "industry": row[4],
809	                        "important_date": row[5],
810	                    }
811	                    for row in database.execute(
812	                        "SELECT id, name, source, region, industry, important_date FROM clients ORDER BY id"
813	                    )
814	                ]
815	                self.respond(200, {RESOURCE: records})
816	
817	        do_GET = do_POST = do_PUT = do_PATCH = do_DELETE = do_HEAD = do_OPTIONS = route
818	
819	    def stop(_signal, _frame):
820	        raise KeyboardInterrupt
821	
822	    signal.signal(signal.SIGTERM, stop)
823	    server = None
824	    try:
825	        server = HTTPServer((args.host, args.port), Handler)
826	        host, port = server.server_address[:2]
827	        address = f"[{host}]" if ":" in host else host
828	        print(f"{PRODUCT} listening on http://{address}:{port}", flush=True)
829	        server.serve_forever()
830	    except KeyboardInterrupt:
831	        pass
832	    finally:
833	        if server is not None:
834	            server.server_close()
835	        database.close()
836	
837	
838	if __name__ == "__main__":
839	    main()
