    selected.clear();
    renderClients();
    renderSelection();
    let refreshed = true;
    try {
      await loadClients();
    } catch (loadErr) {
      refreshed = false;
      // 刷新失败不自动重交刚才的修改，也不要求用户再次保存；旧表格（含勾选状态）
      // 已按保存成功的结果保留/清除，不被读取失败清空。
