    // 请求失败也要结束等待并显示失败，不能使页面一直无法继续使用。
    showBatchReport('<div class="banner bad">批量修改请求失败：' + esc(err.message) + "</div>");
  } finally {
    // 等待结束：是否能保存仍取决于有没有选中客户（成功后已清除勾选）。
    batchSaving = false;
    syncSubmitState();
  }
});

