    '未导入 <b>' + failures.length + '</b> 条。</div>';
  if (failures.length) {
    out += '<div class="failures"><p><b>未导入记录（编号按原文件数据记录，表头不计入）：</b></p><ul>';
    out += failures.map(f =>
      "<li>第 <b>" + esc(f.row) + "</b> 条：" + esc(f.reason) + "</li>").join("");
    out += "</ul></div>";
  }
  showReport(out);
}

