// CDP harness: drive the real page, simulate GET /api/clients failures via fetch hook.
const PORT = process.env.CDP_PORT;
const BASE = "http://127.0.0.1:8247";

const list = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();
const page = list.find(t => t.type === "page");
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise(r => ws.addEventListener("open", r, {once: true}));

let nextId = 1;
const pending = new Map();
ws.addEventListener("message", e => {
  const msg = JSON.parse(e.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
});
function send(method, params = {}) {
  const id = nextId++;
  return new Promise(resolve => { pending.set(id, resolve); ws.send(JSON.stringify({id, method, params})); });
}
async function evalp(expr) {
  const r = await send("Runtime.evaluate", {
    expression: expr, awaitPromise: true, returnByValue: true,
  });
  if (r.result.exceptionDetails) {
    throw new Error("page exception: " + JSON.stringify(r.result.exceptionDetails.exception?.description || r.result.exceptionDetails.text));
  }
  return r.result.result.value;
}
async function waitFor(expr, timeout = 4000) {
  const deadline = Date.now() + timeout;
  while (Date.now() < deadline) {
    const v = await evalp(expr);
    if (v) return v;
    await new Promise(r => setTimeout(r, 50));
  }
  throw new Error("timeout waiting for: " + expr);
}

const HOOK = `
(() => {
  const orig = window.fetch;
  window.fetch = function(input, init) {
    const u = new URL(typeof input === 'string' ? input : input.url, location.origin);
    if (u.pathname === '/api/clients' && !(init && /^(POST|PUT|DELETE)/i.test(init.method || ''))) {
      const mode = window.__mode || 'normal';
      if (mode === 'network') return Promise.reject(new TypeError('Failed to fetch (simulated)'));
      if (mode === 'http500') return Promise.resolve(new Response(JSON.stringify({error:'服务器内部错误（模拟）'}), {status: 500, headers: {'Content-Type': 'application/json'}}));
      if (mode === 'errorjson') return Promise.resolve(new Response(JSON.stringify({error:'坏网关（模拟）'}), {status: 200, headers: {'Content-Type': 'application/json'}}));
      if (mode === 'notjson') return Promise.resolve(new Response('<<< not json >>>', {status: 200}));
      if (mode === 'noclients') return Promise.resolve(new Response(JSON.stringify({unexpected: true}), {status: 200, headers: {'Content-Type': 'application/json'}}));
      if (mode === 'empty') return Promise.resolve(new Response(JSON.stringify({clients: []}), {status: 200, headers: {'Content-Type': 'application/json'}}));
    }
    return orig.apply(this, arguments);
  };
})();
`;

await send("Page.enable");
await send("Runtime.enable");
await send("Page.addScriptToEvaluateOnNewDocument", {source: HOOK});
await send("Page.navigate", {url: BASE + "/"});
await new Promise(r => setTimeout(r, 800)); // let initial loadClients finish

let pass = 0, fail = 0;
function check(label, cond, detail) {
  console.log(cond ? "PASS" : "FAIL", label, detail ?? "");
  cond ? pass++ : fail++;
}

// ---------- Scenario A: save succeeds, refresh: network error ----------
await evalp(`(async () => {
  window.__mode = 'normal';
  await loadClients(); // ensure real rows rendered
  // select clients #1 and #2
  document.querySelectorAll('.row-check').forEach(cb => {
    if (cb.value === '1' || cb.value === '2') { cb.checked = true; cb.dispatchEvent(new Event('change', {bubbles: true})); }
  });
  // set source op to "set", fill value
  const card = document.querySelector('.bf[data-field=source]');
  card.querySelector('input[value=set]').checked = true;
  card.querySelector('input[value=set]').dispatchEvent(new Event('change', {bubbles: true}));
  card.querySelector('.bf-value').value = '新来源A';
  window.__mode = 'network'; // refresh after save will fail
  document.getElementById('batch-form').dispatchEvent(new Event('submit', {bubbles: true, cancelable: true}));
})()`);

await waitFor(`document.querySelector('#batch-report .banner.ok') !== null`);
await new Promise(r => setTimeout(r, 200));
const a = await evalp(`({
  okText: (document.querySelector('#batch-report .banner.ok')||{}).textContent || '',
  warnText: (document.querySelector('#batch-report .banner.warn')||{}).textContent || '',
  badText: (document.querySelector('#batch-report .banner.bad')||{}).textContent || '',
  busyShown: !!document.querySelector('#batch-report .banner.busy'),
  rows: document.querySelectorAll('#clients-body tr').length,
  row1Source: document.querySelector('#clients-body tr[data-id="1"] td:nth-child(4)').textContent,
  row1Checked: document.querySelector('.row-check[value="1"]').checked,
  row3Checked: document.querySelector('.row-check[value="3"]').checked,
  checkAllChecked: document.getElementById('check-all').checked,
  selCount: document.getElementById('sel-count').textContent,
  chips: document.querySelectorAll('.sel-chip').length,
  sourceOp: document.querySelector('.bf[data-field=source] input[value=keep]').checked,
  sourceVal: document.querySelector('.bf[data-field=source] .bf-value').value,
  submitDisabled: document.getElementById('batch-submit').disabled,
  submitText: document.getElementById('batch-submit').textContent,
  emptyShown: document.getElementById('clients-empty').classList.contains('on'),
  loadNoteShown: document.getElementById('clients-load-error').classList.contains('on'),
})`);
check("A 成功横幅显示处理数量 2", /已成功处理\s*2\s*名客户/.test(a.okText), a.okText);
check("A 另有警告说明列表未更新", a.warnText.includes("列表暂未更新") && a.warnText.includes("保存前"), a.warnText);
check("A 警告不宣称已刷新", !/已刷新|相关列已刷新/.test(a.okText + a.warnText), a.okText + a.warnText);
check("A 不出现保存失败横幅", a.badText === "" && !a.busyShown, JSON.stringify(a));
check("A 旧表格三行仍保留", a.rows === 3, String(a.rows));
